const Theme=createContext(null);
const useT=()=>useContext(Theme);
function Icon({name,size=22,color}){const t=useT();return <Ionicons name={name} size={size} color={color||t.text}/>;}
function Label({children,muted=false,style,...props}){const t=useT();return <Text {...props} style={[{color:muted?t.muted:t.text,fontSize:15},style]}>{children}</Text>;}
function Button({title,onPress,secondary=false,icon,disabled=false,style}){const t=useT();return <Touch accessibilityRole="button" accessibilityLabel={title} disabled={disabled} onPress={onPress} style={({pressed})=>[s.button,{backgroundColor:secondary?t.soft:t.button,opacity:disabled?.4:pressed?.9:1,borderWidth:1,borderColor:secondary?t.border:t.button},style]}>{icon&&<Icon name={icon} size={19} color={secondary?t.accent:'#fff'}/>}<Label style={{fontWeight:'700',color:secondary?t.accent:'#fff',fontSize:14}}>{title}</Label></Touch>;}
function Panel({children,style}){const t=useT();return <View style={[s.panel,{backgroundColor:t.glass?t.surface:t.panel,borderColor:t.border,shadowColor:t.mono?'#000000':t.theme.accent},style]}>{t.glass&&<LinearGradient pointerEvents="none" colors={t.dark?['#FFFFFF0C','#FFFFFF00']:['#FFFFFF88','#FFFFFF00']} style={{position:'absolute',top:0,left:0,right:0,height:64,borderTopLeftRadius:28,borderTopRightRadius:28}}/>}{children}</View>;}
function Row({icon,title,sub,value,onPress,right,leading}){const t=useT();const Container=onPress?Pressable:View;return <Container onPress={onPress} accessibilityRole={onPress?'button':undefined} style={onPress?({pressed})=>[s.row,{opacity:pressed?.65:1}]:s.row}>{leading?<View style={{marginRight:12}}>{leading}</View>:icon&&<View style={[s.rowIcon,{backgroundColor:t.soft}]}><Icon name={icon} size={21} color={t.accent}/></View>}<View style={{flex:1}}><Label style={{fontWeight:'600',letterSpacing:-.2}}>{title}</Label>{sub&&<Label muted style={{fontSize:12,lineHeight:18,marginTop:4}}>{sub}</Label>}</View>{value&&<Label muted style={{fontSize:13,maxWidth:130}}>{value}</Label>}{right|| (onPress&&<Icon name="chevron-forward" size={16} color={t.muted}/>)}</Container>;}
function Field({label,value,onChangeText,placeholder,keyboardType='default',...props}){const t=useT();return <View style={{marginBottom:19}}><Label muted style={{fontSize:12,fontWeight:'600',marginBottom:8}}>{label}</Label><TextInput accessibilityLabel={label} value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor={t.muted} keyboardType={keyboardType} style={[s.input,{backgroundColor:t.surface,color:t.text,borderColor:t.border},props.multiline&&{minHeight:120,textAlignVertical:'top'}]} {...props}/></View>;}
function Chips({items,value,onChange}){const t=useT();return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:8,paddingVertical:7}}>{items.map(v=><Pressable accessibilityRole="button" key={v} onPress={()=>onChange(v)} style={[s.chip,{backgroundColor:value===v?t.text:t.soft}]}><Label style={{fontSize:13,fontWeight:'600',color:value===v?t.bg:t.muted}}>{v}</Label></Pressable>)}</ScrollView>;}
function Section({title,action,onPress}){const t=useT();return <View style={[s.between,{marginTop:27,marginBottom:12}]}><Label style={{fontSize:21,fontWeight:'700',letterSpacing:-.6}}>{title}</Label>{action&&<Pressable accessibilityRole="button" onPress={onPress}><Label style={{color:t.accent,fontSize:13,fontWeight:'600'}}>{action}</Label></Pressable>}</View>;}
const BRAND_LOGOS = {"mastercard": "data:image/png;base64,", "visa": "data:image/png;base64,"};
function NetworkLogo({network}){return <Image accessibilityLabel={network} source={{uri:BRAND_LOGOS[network==='Visa'?'visa':'mastercard']}} resizeMode="contain" style={{width:54,height:33,borderRadius:5,backgroundColor:'#FFFFFF'}}/>;}
function CardArt(props){return <CollectorCard {...props} renderNetwork={network=><NetworkLogo network={network}/>}/>;}
function Transactions({items,onPress,hidden}){const t=useT();return items.length?<Panel style={{paddingVertical:2}}>{items.map((x,i)=><Row key={x.id} leading={merchantForTransaction(x)?<MerchantIcon merchant={merchantForTransaction(x)}/>:null} icon={x.value>0?'arrow-down-outline':({Jídlo:'restaurant-outline',Předplatné:'repeat-outline',Doprava:'car-outline',Nákupy:'bag-outline'}[x.category]||'arrow-up-outline')} title={x.name} sub={(x.status&&x.status!=='posted'?paymentStatus(x)+' · ':x.category+' · ')+new Date(x.dueAt||x.date).toLocaleDateString('cs-CZ',{day:'numeric',month:'short'})} onPress={()=>onPress(x)} right={<Label style={[{fontWeight:'700',fontSize:14},x.value>0&&{color:t.positive}]}>{hidden?'••••':(x.value>0?'+':'')+money(x.value,x.currency)}</Label>}/>)}</Panel>:<Panel><Label muted>Zatím žádné transakce.</Label></Panel>;}

