 const insets=useSafeAreaInsets();const system=useColorScheme();const [data,setData]=useState(initial);const stateRef=useRef(data);stateRef.current=data;const [locked,setLocked]=useState(false);const [moment,setMoment]=useState(null);const [commandOpen,setCommandOpen]=useState(false);const [welcome5,setWelcome5]=useState(false);const momentTimer=useRef(null);const [ready,setReady]=useState(false);const [loadError,setLoadError]=useState('');const [tab,setTab]=useState('Přehled');const [homeAnnouncement,setHomeAnnouncement]=useState(false);const homeTab=useRef(tab);homeTab.current=tab;const [sheet,setSheet]=useState(null);const [toast,setToast]=useState('');const [currency,setCurrency]=useState('CZK');const [search,setSearch]=useState('');const [filter,setFilter]=useState('Vše');const [cardIndex,setCardIndex]=useState(0);const [form,setForm]=useState({});const [review,setReview]=useState(null);const saveQueue=useRef(Promise.resolve());const busy=useRef(false);
