 const t=useMemo(()=>({...themeTokens(selectedTheme,dark),glass:data.glass}),[selectedTheme,dark,data.glass]);
 useEffect(()=>{setHomeAnnouncement(!!session&&ready&&!locked&&tab==='Přehled');},[session,ready,locked,tab,u.id]);
