 useEffect(()=>{AsyncStorage.getItem(KEY).then(raw=>{if(raw){const parsed=JSON.parse(raw);if(parsed.version!==2||!Array.isArray(parsed.users)||!parsed.users.length||!parsed.users.every(x=>x.balances&&Array.isArray(x.cards)&&Array.isArray(x.transactions)&&Array.isArray(x.goals)))throw new Error('Neplatná uložená data');const next=processDue(migrate(parsed));const active=next.users.find(x=>x.id===next.active)||next.users[0];active.security.history.unshift({id:makeId(),name:'Otevření lokálního profilu',date:new Date().toISOString()});active.security.history=active.security.history.slice(0,50);setData(next);setLocked(!!active.security.autoLock);stateRef.current=next;}setReady(true);}).catch(()=>{setLoadError('Uložená data se nepodařilo načíst. Zkuste aplikaci znovu otevřít.');});},[]);
