 useEffect(()=>{if(!ready||!session)return;let live=true;AsyncStorage.getItem(V5_WELCOME_KEY).then(v=>{if(live&&!v)setWelcome5(true);}).catch(()=>{});return()=>{live=false;};},[ready,session]);
 useEffect(()=>{if((tab!=='Promo'&&!tab.startsWith('v3:'))||Platform.OS!=='android')return;const sub=BackHandler.addEventListener('hardwareBackPress',()=>{setTab('Přehled');return true;});return()=>sub.remove();},[tab]);
