 const commit=next=>{stateRef.current=next;setData(next);};
 const openSession=id=>{const d=processDue(stateRef.current),target=d.users.find(x=>x.id===id);if(!target)throw Error('Účet nebyl nalezen.');commit({...d,active:id,mode:'Uživatel / Klient',users:d.users.map(x=>x.id===id?{...x,auth:x.auth?{...x.auth,failedAttempts:0,lockedUntil:0}:undefined,security:{...x.security,history:[{id:makeId(),name:'Přihlášení do Zenvault 5',date:today()},...x.security.history].slice(0,50)}}:x)});setSession(id);setLocked(!!target.security.autoLock);setTab('Přehled');setCardIndex(0);setSheet(null);setToast('');};
 const quickLogin=id=>{const target=stateRef.current.users.find(x=>x.id===id);if(!target||target.auth)throw Error('Tento účet vyžaduje heslo.');openSession(id);};
 const login=async(identifier,password,task)=>{const target=findLogin(stateRef.current.users,identifier);if(!target||!password)throw Error('E-mail, telefon nebo heslo nesouhlasí.');if(target.auth.lockedUntil>Date.now())throw Error('Příliš mnoho pokusů. Zkus to znovu za minutu.');const credential=target.auth.credential;let valid=false;try{valid=await verifyPassword(password,credential,task);}catch(e){task?.check();throw Error('Ověření hesla se nepodařilo. Zkus to znovu.');}task?.check();const d=stateRef.current,current=d.users.find(x=>x.id===target.id);if(!current||current.auth.credential.hash!==credential.hash)throw Error('Účet se změnil. Přihlas se znovu.');if(!valid){commit({...d,users:d.users.map(x=>x.id===target.id?{...x,auth:failedLogin(x.auth)}:x)});throw Error('E-mail, telefon nebo heslo nesouhlasí.');}openSession(target.id);};
 const register=async(form,task)=>{task.check();const salt=hex(await task.wait(Crypto.getRandomBytesAsync(16),10000,'Zabezpečení se nepodařilo spustit. Zkus to znovu.'));const credential=await createCredential(form.password,salt,task);task.check();const d=stateRef.current;const created=registerUser(d.users,form,credential);task.check();commit({...d,users:[...d.users,created]});openSession(created.id);};
