 if(locked&&ready)return <Theme.Provider value={t}><LockScreen key={u.id} u={u} ui={ui3} onUnlock={()=>{setLocked(false);editUser(x=>({...x,security:{...x.security,history:[{id:makeId(),name:'Odemknutí profilu',date:new Date().toISOString()},...x.security.history].slice(0,50)}}));}}/></Theme.Provider>;
 if(!ready)return <Theme.Provider value={t}><View style={{flex:1,backgroundColor:t.bg,alignItems:'center',justifyContent:'center',padding:30}}><Label style={{fontSize:34,fontWeight:'800'}}>zenvault®</Label>{loadError?<Label muted style={{marginTop:20,lineHeight:22}}>{loadError}</Label>:<ActivityIndicator color={t.accent} style={{marginTop:20}}/>}</View></Theme.Provider>;
 return <Theme.Provider value={t}><View style={{flex:1,backgroundColor:t.bg}}><StatusBar barStyle={dark?'light-content':'dark-content'} backgroundColor={t.bg}/><ThemeBackdrop theme={selectedTheme} dark={dark} glass={data.glass}/>
 <ScrollView ref={mainScroll} key={tab} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingTop:insets.top+20,paddingHorizontal:22,paddingBottom:120+insets.bottom,width:'100%',maxWidth:760,alignSelf:'center'}}><Enter>{tab.startsWith('v3:')?<V3Page key={tab} section={tab.slice(3)} {...v3props}/>:tab==='Promo'?promo():tab==='Přehled'?home():tab==='Platby'?payments():tab==='Karty'?cardsPage():tab==='Spoření'?<V3Page key="vaults" section="vaults" {...v3props}/>:tab==='Přehledy'?<V3Page key="insights" section="insights" {...v3props}/>:settings()}</Enter></ScrollView>
 <View style={{position:'absolute',bottom:Math.max(insets.bottom,12),left:16,right:16,alignItems:'center'}}><View style={[s.nav,{backgroundColor:data.glass?t.surface:t.panel,borderColor:t.border}]}>{data.glass&&<LinearGradient pointerEvents="none" colors={['#ffffff24','#ffffff00']} style={[StyleSheet.absoluteFill,{borderRadius:29}]}/>}{[['Přehled','home-outline'],['Platby','swap-horizontal-outline'],['Karty','card-outline'],['Spoření','sparkles-outline'],['Nastavení','settings-outline']].map(([name,icon])=><Pressable key={name} accessibilityRole="tab" accessibilityLabel={name} accessibilityState={{selected:tab===name||(tab==='Promo'&&name==='Přehled')}} onPress={()=>{if(name==='Přehled')setHomeAnnouncement(true);setTab(name);}} style={{flex:1,alignItems:'center',paddingVertical:11,gap:5,backgroundColor:(tab===name||(tab==='Promo'&&name==='Přehled'))?(dark?'#FFFFFF1D':t.soft):'transparent',borderRadius:23}}><Icon name={icon} size={21} color={(tab===name||(tab==='Promo'&&name==='Přehled'))?t.accent:t.muted}/><Label style={{fontSize:9,fontWeight:'600',color:(tab===name||(tab==='Promo'&&name==='Přehled'))?t.accent:t.muted}}>{name}</Label></Pressable>)}</View></View>
 <Modal visible={!!sheet} transparent animationType={reduced?'none':'slide'} onRequestClose={close} statusBarTranslucent><View style={{flex:1,backgroundColor:t.mono?'#00000066':'#03142677',justifyContent:'flex-end'}}><Pressable accessibilityLabel="Zavřít dialog" style={StyleSheet.absoluteFill} onPress={close}/><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={{maxHeight:'92%',width:'100%',maxWidth:620,alignSelf:'center'}}><View style={{backgroundColor:t.bg,borderTopLeftRadius:30,borderTopRightRadius:30,overflow:'hidden',flexShrink:1}}><View style={{height:5,width:34,borderRadius:5,backgroundColor:t.border,alignSelf:'center',marginTop:10}}/><View style={[s.between,{padding:22,paddingBottom:14}]}><Label style={{fontSize:23,fontWeight:'700',letterSpacing:-.7,flex:1}}>{sheet?sheetTitles[sheet.type]:''}</Label><Pressable accessibilityRole="button" accessibilityLabel="Zavřít" onPress={close} style={{padding:7,backgroundColor:t.soft,borderRadius:20}}><Icon name="close" size={20}/></Pressable></View><ScrollView ref={sheetScroll} keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingHorizontal:22,paddingTop:7,paddingBottom:Math.max(insets.bottom,20)+18}}>{sheetBody()}</ScrollView></View></KeyboardAvoidingView>{toast!==''&&<View pointerEvents="none" style={[s.toast,{top:insets.top+6,backgroundColor:t.mono?'#000000':'#173753'}]}><Text style={{color:'#fff',fontWeight:'600',textAlign:'center'}}>{toast}</Text></View>}</View></Modal>
 {toast!==''&&!sheet&&<View pointerEvents="none" style={[s.toast,{top:insets.top+6,backgroundColor:t.mono?'#000000':'#173753'}]}><Text style={{color:'#fff',fontWeight:'600',textAlign:'center'}}>{toast}</Text></View>}
 <MembershipAnnouncement mono={t.mono} visible={!!session&&homeAnnouncement&&tab==='Přehled'&&!locked&&!sheet&&!moment&&!welcome5&&!commandOpen} u={u} onClose={()=>setHomeAnnouncement(false)} onExplore={id=>{setHomeAnnouncement(false);if(id==='prestige')open('tiers');else if(id==='promo')setTab('Promo');else goV3('cardpay');}}/>
 <CommandCenter5 visible={commandOpen} u={u} ui={ui3} onClose={()=>setCommandOpen(false)} onGo={goV3} onOpen={openFromV3} onTransaction={transaction=>open('transaction',{transaction})}/>
 <Welcome5 visible={!!session&&welcome5&&!locked} ui={ui3} onDone={()=>{setWelcome5(false);AsyncStorage.setItem(V5_WELCOME_KEY,'done').catch(()=>{});}}/>
 <PaymentMoment moment={moment} onClose={()=>setMoment(null)} ui={ui3}/>
 </View></Theme.Provider>;
